from solution import change_base
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def _ref_change_base(x: int, base: int) -> str:
    # Obviously-correct reference model for non-negative x and base >= 2.
    assert isinstance(x, int) and x >= 0
    assert isinstance(base, int) and base >= 2
    if x == 0:
        return "0"
    digits = []
    v = x
    while v > 0:
        digits.append(str(v % base))
        v //= base
    return "".join(reversed(digits))


# ---- explicit examples from the spec docstring ----

def test_example_8_base3():
    assert change_base(8, 3) == '22'

def test_example_8_base2():
    assert change_base(8, 2) == '1000'

def test_example_7_base2():
    assert change_base(7, 2) == '111'


# ---- zero / single digit boundaries ----

def test_zero_returns_zero_string():
    # 0 in any valid base is "0", never empty.
    for base in [2, 3, 5, 8, 9]:
        assert change_base(0, base) == "0"

def test_single_digit_values():
    # x < base must be a single digit equal to str(x).
    for base in [2, 3, 5, 9]:
        for x in range(base):
            assert change_base(x, base) == str(x)


# ---- property: round-trip via int(..., base) ----

@given(
    x=st.integers(min_value=0, max_value=10_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_roundtrip_int_parse(x, base):
    s = change_base(x, base)
    assert isinstance(s, str)
    assert int(s, base) == x

@given(
    x=st.integers(min_value=0, max_value=10**12),
    base=st.integers(min_value=2, max_value=9),
)
def test_roundtrip_large_values(x, base):
    s = change_base(x, base)
    assert int(s, base) == x


# ---- property: equivalence to reference model ----

@given(
    x=st.integers(min_value=0, max_value=50_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_equivalence_to_reference_model(x, base):
    assert change_base(x, base) == _ref_change_base(x, base)


# ---- property: digits are in range ----

@given(
    x=st.integers(min_value=0, max_value=20_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_digits_in_valid_range(x, base):
    s = change_base(x, base)
    assert len(s) >= 1
    assert all(c.isdigit() for c in s)
    assert all(0 <= int(c) < base for c in s)


# ---- property: no leading zeros, non-empty ----

@given(
    x=st.integers(min_value=0, max_value=20_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_no_leading_zeros_and_nonempty(x, base):
    s = change_base(x, base)
    assert isinstance(s, str)
    assert len(s) > 0
    if len(s) > 1:
        assert s[0] != "0"


# ---- property: powers of base ----

@given(
    base=st.integers(min_value=2, max_value=9),
    k=st.integers(min_value=0, max_value=10),
)
def test_power_of_base_is_one_followed_by_zeros(base, k):
    assert change_base(base ** k, base) == "1" + "0" * k

@given(
    base=st.integers(min_value=2, max_value=9),
    k=st.integers(min_value=1, max_value=8),
)
def test_power_of_base_minus_one_is_all_max_digits(base, k):
    assert change_base(base ** k - 1, base) == str(base - 1) * k

@given(
    base=st.integers(min_value=2, max_value=9),
    k=st.integers(min_value=1, max_value=8),
)
def test_power_of_base_plus_one_boundaries(base, k):
    # base**k + 1 -> 1 followed by (k-1) zeros then 1
    assert change_base(base ** k + 1, base) == "1" + "0" * (k - 1) + "1"


# ---- property: result type is str and length grows correctly ----

@given(
    x=st.integers(min_value=0, max_value=5000),
    base=st.integers(min_value=2, max_value=9),
)
def test_result_is_decimal_free_string(x, base):
    s = change_base(x, base)
    assert isinstance(s, str)
    # must match reference length exactly (catches truncation/padding)
    assert len(s) == len(_ref_change_base(x, base))
